import{_ as a,o as n,c as i,ag as r}from"./chunks/framework.Drp2S_UI.js";const m=JSON.parse('{"title":"Engineering records and acceptance","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/engineering-records.md","filePath":"en/guide/engineering-records.md","lastUpdated":1792653875000}'),t={name:"en/guide/engineering-records.md"};function o(l,e,s,d,c,h){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="engineering-records-and-acceptance" tabindex="-1">Engineering records and acceptance <a class="header-anchor" href="#engineering-records-and-acceptance" aria-label="Permalink to &quot;Engineering records and acceptance&quot;">​</a></h1><p>Use <a href="./start.html">quick start</a>, <a href="./architecture.html">current architecture</a>, <a href="./rendering-pipeline.html">rendering pipeline</a> and API references for integration. Staged designs below preserve provenance and may describe incomplete states at the time they were written; they are not the current API contract.</p><h2 id="current-conclusions" tabindex="-1">Current conclusions <a class="header-anchor" href="#current-conclusions" aria-label="Permalink to &quot;Current conclusions&quot;">​</a></h2><p>T1–T24 legacy removal and HarfBuzz-only migration are complete. Final T23/T24 regression finished on 2026-10-22. Canvas-only pages and ESM-only distribution are current constraints. Native incremental layout still has significant costs; passing regression does not close unresolved performance work.</p><p>Original acceptance evidence is maintained in Chinese:</p><ul><li><a href="./../../guide/native-release-acceptance.html">Final acceptance</a>: environment, package consumption, browsers, memory and performance.</li><li><a href="./../../guide/native-regression.html">Native regression</a>: test entry points and coverage.</li><li><a href="./../../guide/legacy-removal-tasks.html">Task plan</a>, <a href="./../../guide/legacy-removal-plan.html">removal design</a> and <a href="./../../guide/legacy-removal-baseline.html">historical baseline</a>.</li></ul><h2 id="implementation-records" tabindex="-1">Implementation records <a class="header-anchor" href="#implementation-records" aria-label="Permalink to &quot;Implementation records&quot;">​</a></h2><p>These original staged records are in Chinese unless an English page exists.</p><ul><li><a href="./../../guide/harfbuzz-shaping.html">Shaping</a>, <a href="./../../guide/harfbuzz-glyph-rendering.html">glyph painting</a>, <a href="./../../guide/layout-protocol.html">layout protocol</a>, <a href="./../../guide/layout-geometry.html">geometry</a>.</li><li><a href="./../../guide/font-resolver.html">Font resolution</a>, <a href="./../../guide/font-coverage.html">coverage</a>, <a href="./../../guide/font-download.html">downloads</a>, <a href="./../../guide/bunny-font-provider.html">Bunny</a>, <a href="./../../guide/editor-ready.html">readiness</a>.</li><li>Chinese native-model records: <a href="./../../guide/native-paragraph-layout.html">paragraphs</a>, <a href="./../../guide/native-object-layout.html">objects</a>, <a href="./../../guide/native-table-layout.html">tables</a>, <a href="./../../guide/native-document-flow.html">document flow</a>, <a href="./../../guide/native-chrome-layout.html">page chrome</a>, <a href="./../../guide/native-auxiliary-layout.html">auxiliary text</a>, <a href="./../../guide/native-interaction-geometry.html">interaction</a>, <a href="./../../guide/native-model-separation.html">model separation</a>, <a href="./../../guide/native-incremental-layout.html">incremental layout</a> and <a href="./../../guide/native-only-engine.html">sole engine</a>.</li><li><a href="./../../guide/public-api-migration.html">Public API migration</a>, <a href="./rtl-layout-design.html">RTL design</a>, <a href="./rtl-deferred-todo.html">RTL follow-ups</a> and <a href="./../../guide/main-integration-2026-10-16.html">main integration</a>.</li></ul><h2 id="deferred-svg-design" tabindex="-1">Deferred SVG design <a class="header-anchor" href="#deferred-svg-design" aria-label="Permalink to &quot;Deferred SVG design&quot;">​</a></h2><p>The <a href="./../../guide/harfbuzz-svg-assessment.html">HarfBuzz-to-SVG assessment</a> is a future proposal. SVG-01 through SVG-12 have not started. Use Canvas today; diagrams in a proposal do not introduce a supported renderer option.</p><h2 id="maintaining-documentation" tabindex="-1">Maintaining documentation <a class="header-anchor" href="#maintaining-documentation" aria-label="Permalink to &quot;Maintaining documentation&quot;">​</a></h2><p>Keep primary Chinese/English guides aligned. Original Chinese measurements remain engineering evidence with explicit links from English. Update current guides with implementation changes, but do not rewrite historical measurements or baseline commits to match the present. Mermaid syntax is checked at build time and diagrams render in the browser. See <a href="./docs-deployment.html">deployment</a>.</p>',13)])])}const u=a(t,[["render",o]]);export{m as __pageData,u as default};
